def transform(grid):
    # Each rectangle's concentric layers are recolored by reversing the palette
    # of that object's rings, detected by geometric rectangular layers.
    out=[r[:] for r in grid]
    R,C=len(grid),len(grid[0])
    # Find bounding boxes of nonzero components, allowing adjacent nested layers to connect.
    from collections import deque
    seen=set()
    for r in range(R):
      for c in range(C):
        if grid[r][c]==0 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); pts=[]
        while q:
          x,y=q.popleft(); pts.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<R and 0<=b<C and grid[a][b]!=0 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
        r0=min(x for x,y in pts);r1=max(x for x,y in pts);c0=min(y for x,y in pts);c1=max(y for x,y in pts)
        layers=[]
        for k in range(min((r1-r0)//2,(c1-c0)//2)+1):
          vals=[grid[x][y] for x,y in pts if min(x-r0,r1-x,y-c0,c1-y)==k]
          if vals: layers.append(vals[0])
        for x,y in pts:
